/* ============================================================
   Bundled fonts.
   ------------------------------------------------------------
   Declaring these with @font-face does not work on this page: the
   WebView serves the app from file:///android_asset/ and drops the
   face however it is referenced. So the bytes are registered here
   instead, and two routes are tried in order — straight from an
   ArrayBuffer, then via a blob: URL, which is same-origin and not
   subject to the file:// restriction.

   Everything is wrapped: a throw in this file used to leave the
   status variable uninitialised, and the reader read that as "the
   font is fine" — a failure that reported itself as success.

   Generated file: do not hand-edit.
   ============================================================ */

var BUNDLED_FONTS = [
    { family: 'UthmanicHafs', weight: '400', data: '' },
    { family: 'Thmanyah', weight: '300', data: '' },
    { family: 'Thmanyah', weight: '400', data: '' },
    { family: 'Thmanyah', weight: '700', data: '' },
    { family: 'Thmanyah', weight: '900', data: '' }
];

/* Plain strings so a screenshot of the reader says what happened. */
var fontLoadStatus = 'لم يبدأ';
var bundledFontsReady;

(function () {
    function bytes(b64) {
        var bin = atob(b64);
        var buf = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
        return buf;
    }

    /* Route 1: hand the decoded bytes straight to FontFace. */
    function viaBuffer(f) {
        return new FontFace(f.family, bytes(f.data).buffer,
            { weight: f.weight, style: 'normal' }).load();
    }

    /* Route 2: same bytes behind a blob: URL. */
    function viaBlob(f) {
        var url = URL.createObjectURL(
            new Blob([bytes(f.data)], { type: 'font/woff2' }));
        return new FontFace(f.family, 'url(' + url + ')',
            { weight: f.weight, style: 'normal' }).load();
    }

    try {
        if (typeof FontFace === 'undefined' || !document.fonts) {
            fontLoadStatus = 'المتصفح لا يدعم تحميل الخطوط';
            bundledFontsReady = Promise.resolve(false);
            return;
        }

        var jobs = BUNDLED_FONTS.map(function (f) {
            return viaBuffer(f)
                .catch(function () { return viaBlob(f); })
                .then(function (face) { document.fonts.add(face); return true; })
                .catch(function (e) {
                    fontLoadStatus = 'فشل التحميل: ' + (e && e.message ? e.message : e);
                    return false;
                });
        });

        bundledFontsReady = Promise.all(jobs).then(function (r) {
            var ok = r.every(Boolean);
            if (ok && fontLoadStatus === 'لم يبدأ') fontLoadStatus = 'تم التسجيل';
            return ok;
        });
    } catch (e) {
        fontLoadStatus = 'خطأ: ' + (e && e.message ? e.message : e);
        bundledFontsReady = Promise.resolve(false);
    }
})();

/**
 * Is a family actually being used to draw text?
 *
 * Registering a face and having it applied are different things, and the
 * earlier check only proved the first. This measures a string in the family
 * against the same string in a known fallback: different widths mean the
 * real face is doing the drawing.
 */
function fontIsRendering(family) {
    try {
        var probe = document.createElement('span');
        probe.textContent = 'الحمد لله رب العالمين ۝١٢٣';
        probe.style.cssText =
            'position:absolute;left:-9999px;top:-9999px;font-size:80px;white-space:nowrap;';
        document.body.appendChild(probe);

        probe.style.fontFamily = 'monospace';
        var base = probe.getBoundingClientRect().width;
        probe.style.fontFamily = "'" + family + "', monospace";
        var test = probe.getBoundingClientRect().width;

        document.body.removeChild(probe);
        return Math.abs(test - base) > 1;
    } catch (e) {
        return false;
    }
}
